export type ParsedConfigureMarketInstruction<
  TProgram extends string = typeof MY_DEFI_DAPP_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    admin: TAccountMetas[0];
    exchange: TAccountMetas[1];
    /** that `Account<Market>` can't read, so the handler migrates and validates it by hand. */
    market: TAccountMetas[2];
    history: TAccountMetas[3];
    liquidationFeed: TAccountMetas[4];
    systemProgram: TAccountMetas[5];
  };
  data: ConfigureMarketInstructionData;
};

export function parseConfigureMarketInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedConfigureMarketInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 6) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 6,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      admin: getNextAccount(),
      exchange: getNextAccount(),
      market: getNextAccount(),
      history: getNextAccount(),
      liquidationFeed: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getConfigureMarketInstructionDataDecoder().decode(instruction.data),
  };
}
